from __future__ import annotations

import tempfile
from pathlib import Path

import pytest

from slurmtui.config.loader import config_from_dict
from slurmtui.config.schema import Config
from slurmtui.data.service import DataService
from slurmtui.data.sources import build_service
from slurmtui.slurm.text_backend import TextBackend

FIXTURE_DIR = Path(__file__).parent / "fixtures" / "hybrid-cloud"


class FixtureBackend(TextBackend):
    """Replays the command outputs generated by tools/make_test_fixtures.py."""

    name = "fixture"

    def __init__(self, directory: Path) -> None:
        self.directory = directory
        super().__init__(self._read("whoami").strip() or "demo")

    def _read(self, name: str) -> str:
        path = self.directory / f"{name}.txt"
        return path.read_text(encoding="utf-8") if path.exists() else ""


DEMO_SITE = {
    "node_groups": [
        {"name": "z3", "nodes": ["htc-*"], "partitions": ["re:^(?!gcp)"]},
        {"name": "GCP", "nodes": ["cmp*", "gpu*"], "partitions": ["gcp*"]},
    ],
    "hardware": {
        "gpu_type": {
            "rules": [
                {"feature": "re:^([A-Z0-9-]+?)-(\\d+GB)$", "label": "{feature.1} {feature.2}"},
                {"gres_type": "re:^(.*?)(-gcp)?(-npr)?$", "label": "{gres_type.1}"},
            ]
        },
        "cpu_type": {
            "rules": [
                {
                    "features": "re:(?:^|,)(Intel|AMD),(?:Xeon,)?([A-Za-z]+\\d[A-Za-z0-9]*)",
                    "label": "{features.1} {features.2}",
                },
                {"feature": "virtual", "label": "virtual"},
            ]
        },
    },
    "sources": {"account_usage": {"enabled": True}, "recent_jobs": {"enabled": True}},
    "tabs": {
        "accounts": {
            "columns": [
                "account",
                "shares",
                "usage",
                "level_fs",
                "jobs_running",
                "jobs_pending",
                "cpus",
                "gpus",
                "memory",
                "members_active",
                "oldest_pending",
                "cpu_hours:*",
                "gpu_hours:*",
            ]
        },
        "users": {"columns": ["user", "jobs_running", "jobs_pending", "cpus", "gpus", "memory", "jobs_24h", "jobs_7d"]},
    },
}


@pytest.fixture(scope="session")
def demo_dir() -> Path:
    """The generated hybrid on-premise/cloud cluster."""
    return FIXTURE_DIR


@pytest.fixture
def demo_config() -> Config:
    return config_from_dict(DEMO_SITE)


@pytest.fixture
def backend(demo_dir: Path) -> FixtureBackend:
    return FixtureBackend(demo_dir)


@pytest.fixture
def service(demo_config: Config, backend: FixtureBackend) -> DataService:
    return build_service(demo_config, backend)


@pytest.fixture
def tmp_state_path() -> Path:
    return Path(tempfile.mkdtemp()) / "state.json"


def read(demo_dir: Path, name: str) -> str:
    return (demo_dir / f"{name}.txt").read_text()
